package clobclient

import (
	"context"
	"errors"
	"strings"
	"testing"
)

// Fixed Polygon vectors from ts-sdk 1462212 wallet.test.ts, not generated by this implementation.
func TestDetectSignatureType(t *testing.T) {
	owner := "0x0000000000000000000000000000000000000001"
	for _, tc := range []struct {
		wallet string
		want   SignatureType
	}{
		{owner, SignatureTypeEOA},
		{"0x7754536ecd85c00b2e0cf9c1aa679340d8550756", SignatureTypePolyProxy},
		{"0x766b6851a199bf91ae3fa13b1cfac5187355118f", SignatureTypePolyGnosisSafe},
		{"0x94bf330955a0b957662feaf878de77bf25f76cd9", SignatureTypePoly1271},
	} {
		for _, wallet := range []string{tc.wallet, " 0x" + strings.ToUpper(tc.wallet[2:]) + " "} {
			got, err := DetectSignatureType(" "+owner+" ", wallet, 137)
			if err != nil || got != tc.want {
				t.Errorf("wallet %s: type %d, err %v", wallet, got, err)
			}
		}
	}
	got, err := DetectSignatureType(poly1271TestEOA, "0x12d77BcbDC3E67F5Da4Dc8e798623482D4a711db", 80002)
	if err != nil || got != SignatureTypePoly1271 {
		t.Fatalf("Amoy: %d %v", got, err)
	}
}

func TestDetectSignatureTypeRejectsUnknown(t *testing.T) {
	owner := "0x0000000000000000000000000000000000000001"
	for _, tc := range []struct {
		signer, wallet string
		chain          int64
		unknown        bool
	}{
		{"", owner, 137, false}, {owner, "bad", 137, false},
		{"0x0000000000000000000000000000000000000000", owner, 137, false},
		{owner, "0x0000000000000000000000000000000000000000", 137, false},
		{owner, owner, 1, false}, {owner, owner, 0, false},
		{owner, "0x0000000000000000000000000000000000000002", 137, true},
		// Historical UUPS Polygon wallets are not supported by the current signing ownership check.
		{owner, "0x57ffbc34de23124faeb8387fcd689d314e57accd", 137, true},
		{owner, "0x7754536ecd85c00b2e0cf9c1aa679340d8550756", 80002, true},
	} {
		got, err := DetectSignatureType(tc.signer, tc.wallet, tc.chain)
		if err == nil || got != SignatureTypeUnknown {
			t.Errorf("%+v: %d %v", tc, got, err)
		}
		if tc.unknown && !errors.Is(err, ErrUnknownWallet) {
			t.Errorf("expected ErrUnknownWallet, got %v", err)
		}
	}
}

func TestWithDetectedSignatureType(t *testing.T) {
	c := newOrderBuilderTestClient(t)
	wallet, err := c.DepositWalletAddress()
	if err != nil {
		t.Fatal(err)
	}
	updated, err := c.WithDetectedSignatureType(strings.ToLower(wallet))
	if err != nil {
		t.Fatal(err)
	}
	if updated.SignatureType() != SignatureTypePoly1271 || updated.FunderAddress() != wallet {
		t.Fatal("wrong detected config")
	}
	if c.SignatureType() != SignatureTypeEOA || c.FunderAddress() != "" {
		t.Fatal("original client mutated")
	}
	if _, err := updated.CreateOrder(context.Background(), CreateOrderParams{TokenID: "123", Price: "0.5", Size: "10", Side: SideBuy, TickSize: TickSizeCent}); err != nil {
		t.Fatal(err)
	}
	eoa, err := updated.WithDetectedSignatureType(c.signer.Address())
	if err != nil || eoa.SignatureType() != SignatureTypeEOA {
		t.Fatalf("EOA: %v", err)
	}
	if _, err := updated.WithDetectedSignatureType("0x0000000000000000000000000000000000000002"); !errors.Is(err, ErrUnknownWallet) {
		t.Fatal(err)
	}
	if updated.SignatureType() != SignatureTypePoly1271 {
		t.Fatal("failed detection mutated client")
	}
	var nilClient *Client
	if _, err := nilClient.WithDetectedSignatureType(wallet); err == nil {
		t.Fatal("nil client accepted")
	}
	empty, err := NewClient(ClientConfig{})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := empty.WithDetectedSignatureType(wallet); err == nil {
		t.Fatal("missing signer accepted")
	}
}
